      hu: "A Kabulhoz közeli Karga-víztározó népszerű családi kirándulóhely. Festői környezetben kínál csónakázási és piknikezési lehetőséget a látogatóknak.",
      ro: "Lacul de acumulare Qargha de lângă Kabul este o destinație populară pentru familii. Oferă oportunități de plimbări cu barca și picnicuri într-un cadru pitoresc.",
      en: "The Qargha Reservoir near Kabul is a popular destination for families. It offers opportunities for boating and picnics in a picturesque setting.",
