      hu: ["Kabul közelében található.", "Öntözési célokat szolgál.", "Golfpálya is van mellette.", "1933-ban épült."],
      ro: ["Situat lângă Kabul.", "Folosit pentru irigații.", "Are un teren de golf.", "Construit în 1933."],
      en: ["Located near Kabul.", "Used for irrigation.", "Features a golf course.", "Constructed in 1933."],
      es: ["Puesta en marcha de la presa en 1933.", "Zona recreativa popular cerca de la capital.", "La altura de la presa es de unos 30 metros.", "Apoya la agricultura local."],
      pt: ["Entrada em funcionamento da barragem em 1933.", "Zona de lazer popular perto da capital.", "A altura da barragem é de cerca de 30 metros.", "Apoia a agricultura local."],
