      es: ["Fundado en 1919 en Kabul.", "La colección incluía más de 100.000 objetos.", "Gravemente dañado durante la guerra civil.", "Muchos tesoros fueron escondidos por el personal.", "Alberga el famoso oro de Bactria.", "Reapertura tras una extensa restauración.", "Muestra la diversa historia cultural del país.", "Situado en el centro histórico de Kabul."],
      pt: ["Fundado em 1919 em Cabul.", "A coleção incluía outrora mais de 100.000 objetos.", "Gravemente danificado durante a guerra civil.", "Muitos tesouros foram escondidos pelos funcionários.", "Abriga o famoso ouro de Báctria.", "Reabertura após uma restauração extensiva.", "Mostra a diversificada história cultural do país.", "Localizado no centro histórico de Cabul."],
      fr: ["Fondé en 1919 à Kaboul.", "La collection comprenait autrefois plus de 100 000 objets.", "Gravement endommagé pendant la guerre civile.", "De nombreux trésors ont été cachés par les employés.", "Abrite l'or célèbre de Bactriane.", "Réouverture après une restauration importante.", "Présente l'histoire culturelle diversifiée du pays.", "Situé dans le centre historique de Kaboul."],
