      es: ["Construida a finales del siglo XIX.", "Lugar principal para las oraciones nacionales del Eid.", "El nombre significa \"lugar de la oración festiva\".", "Aquí se han hecho anuncios políticos importantes.", "Se encuentra en el este de Kabul.", "Históricamente más significativa que muchas mezquitas más grandes.", "Escenario de ceremonias de coronación.", "Gran patio abierto para miles de personas."],
      pt: ["Construída no final do século XIX.", "Local principal para as orações nacionais do Eid.", "O nome significa \"local de oração festiva\".", "Foram feitos aqui anúncios políticos importantes.", "Localizada no leste de Cabul.", "Historicamente mais significativa do que muitas mesquitas maiores.", "Palco de cerimónias de coroação.", "Grande pátio aberto para milhares de pessoas."],
      fr: ["Construite à la fin du XIXe siècle.", "Lieu principal pour les prières nationales de l'Aïd.", "Le nom signifie « lieu de la prière de fête ».", "D'importantes annonces politiques y ont été faites.", "Située dans l'est de Kaboul.", "Historiquement plus importante que beaucoup de mosquées plus grandes.", "Théâtre de cérémonies de couronnement.", "Vaste cour ouverte pouvant accueillir des milliers de personnes."],
