      de: "Mit ihrer markanten blauen Kuppel ist diese Moschee im belebten Zentrum Kabuls nicht zu übersehen. Sie ist ein architektonisches Highlight der Altstadt.",
      hu: "Jellegzetes kék kupolájával ez a mecset Kabul nyüzsgő központjában azonnal szembetűnik. Az óváros építészeti fénypontja.",
      ro: "Cu cupola sa albastră distinctivă, această moschee din centrul aglomerat al Kabulului este de neratat. Este un reper arhitectural al orașului vechi.",
      en: "With its striking blue dome, this mosque in the bustling center of Kabul cannot be missed. It is an architectural highlight of the old town.",
      es: "Con su distintiva cúpula azul, esta mezquita en el animado centro de Kabul es imposible de pasar por alto. Es un hito arquitectónico del casco antiguo.",
      pt: "Com a sua cúpula azul distinta, esta mesquita no movimentado centro de Cabul é impossível de ignorar. É um destaque arquitetónico da cidade velha.",
