      es: ["Construida en la década de 1920.", "Arquitectura inspirada en el estilo europeo.", "Diseño muy atípico para una mezquita.", "Ubicada directamente a orillas del río Kabul.", "Nombrada en honor a un conquistador árabe.", "Parte de la modernización del rey Amanulá Khan.", "Posee fachadas de estuco y balcones.", "Edificio llamativo de dos plantas."],
      pt: ["Construída na década de 1920.", "Arquitetura inspirada no estilo europeu.", "Design muito atípico para uma mesquita.", "Localizada diretamente nas margens do rio Cabul.", "Nomeada em homenagem a um conquistador árabe.", "Parte da modernização do rei Amanullah Khan.", "Possui fachadas de estuque e varandas.", "Edifício de dois andares muito chamativo."],
      fr: ["Construite dans les années 1920.", "Architecture inspirée du style européen.", "Conception très atypique pour une mosquée.", "Située directement sur les rives de la rivière Kaboul.", "Nommée d'après un conquérant arabe.", "Fait partie de la modernisation du roi Amanullah Khan.", "Possède des façades en stuc et des balcons.", "Édifice remarquable de deux étages."],
