      pt: ["O nome significa \"Palácio das quarenta colunas\".", "Extensivamente restaurado e reaberto em 2019.", "Situado num grande parque público.", "Originalmente construído no século XIX.", "Serviu como casa de hóspedes do governo.", "Símbolo da reconstrução no Afeganistão.", "Local importante para eventos estatais.", "Local de lazer popular para a população urbana."],
