      en: ["Built during the reign of Abdur Rahman Khan", "Constructed in the late 19th century", "Includes a fortified citadel known as the Arg", "Located in the heart of Kabul city"],
      es: ["Construido a partir de 1880 bajo el emir Abdur Rahman Khan", "Se encuentra en un terreno de 34 hectáreas", "Consta de varios palacios y jardines", "Antigua sede de los monarcas afganos"],
      pt: ["Construído a partir de 1880 sob o emir Abdur Rahman Khan", "Localizado num terreno de 34 hectares", "Composto por vários palácios e jardins", "Antiga sede dos monarcas afegãos"],
