    descriptionAdvanced: {
      de: "Die Arg ist der Präsidentenpalast Afghanistans und das pulsierende Herz der Macht in Kabul. Der Name „Arg“ bedeutet Zitadelle, was seine Funktion als befestigter Komplex unterstreicht. Errichtet wurde die Anlage Ende des 19. Jahrhunderts unter Emir Abdur Rahman Khan und dient seitdem als Sitz der Staatsoberhäupter. Der Komplex umfasst nicht nur die offiziellen Amtsräume des Präsidenten, sondern auch Wohnquartiere und Verwaltungsgebäude, umgeben von hohen Mauern. Die Arg war Schauplatz unzähliger historischer Ereignisse, von Staatsstreichen bis hin zu feierlichen Zeremonien. Ihre Mauern haben das Kommen und Gehen von Königen, Präsidenten und Regierungen miterlebt. Als Symbol der staatlichen Autorität ist die Arg ein zentraler und stark gesicherter Ort, der die komplexe und oft turbulente politische Geschichte Afghanistans verkörpert.",
      hu: "Az Arg Afganisztán elnöki palotája és a hatalom lüktető szíve Kabulban. Az „Arg” név citadellát jelent, ami erődített komplexum jellegét hangsúlyozza. A komplexumot a 19. század végén építtette Abdur Rahman kán, és azóta az államfők székhelyéül szolgál. A komplexum nemcsak az elnök hivatalos irodáit foglalja magában, hanem lakónegyedeket és közigazgatási épületeket is, amelyeket magas falak vesznek körül. Az Arg számtalan történelmi esemény helyszíne volt, az államcsínyektől az ünnepélyes szertartásokig. Falai királyok, elnökök és kormányok jövés-menését látták. Az állami tekintély szimbólumaként az Arg egy központi és erősen őrzött hely, amely Afganisztán összetett és gyakran viharos politikai történelmét testesíti meg.",
      ro: "Arg este palatul prezidențial al Afganistanului și inima vibrantă a puterii în Kabul. Numele „Arg” înseamnă citadelă, ceea ce subliniază funcția sa de complex fortificat. Complexul a fost construit la sfârșitul secolului al XIX-lea sub emirul Abdur Rahman Khan și de atunci servește drept reședință a șefilor de stat. Complexul include nu numai birourile oficiale ale președintelui, ci și cartiere de locuit și clădiri administrative, înconjurate de ziduri înalte. Arg a fost scena a nenumărate evenimente istorice, de la lovituri de stat la ceremonii solemne. Zidurile sale au fost martore la venirea și plecarea regilor, președinților și guvernelor. Ca simbol al autorității statului, Arg este un loc central și puternic securizat, care întruchipează istoria politică complexă și adesea turbulentă a Afganistanului.",
      en: "The Arg is the presidential palace of Afghanistan and the vibrant heart of power in Kabul. The name 'Arg' means citadel, which underscores its function as a fortified complex. The compound was built in the late 19th century under Emir Abdur Rahman Khan and has served as the seat of heads of state ever since. The complex includes not only the president's official offices but also residential quarters and administrative buildings, all surrounded by high walls. The Arg has been the scene of countless historical events, from coups to solemn ceremonies. Its walls have witnessed the coming and going of kings, presidents, and governments. As a symbol of state authority, the Arg is a central and heavily guarded location that embodies the complex and often turbulent political history of Afghanistan.",
      es: "El Arg es el palacio presidencial de Afganistán y el corazón pulsante del poder en Kabul. El nombre \"Arg\" significa ciudadela, lo que subraya su función como complejo fortificado. La instalación fue construida a finales del siglo XIX bajo el mando del emir Abdur Rahman Khan y desde entonces sirve como sede de los jefes de estado. El complejo incluye no solo las oficinas oficiales del presidente, sino también barrios residenciales y edificios administrativos, rodeados de altos muros. El Arg ha sido escenario de innumerables eventos históricos, desde golpes de estado hasta ceremonias solemnes. Sus muros han presenciado la llegada y partida de reyes, presidentes y gobiernos. Como símbolo de la autoridad estatal, el Arg es un lugar central y fuertemente custodiado que encarna la compleja y a menudo turbulenta historia política de Afganistán.",
      pt: "O Arg é o palácio presidencial do Afeganistão e o coração pulsante do poder em Cabul. O nome \"Arg\" significa cidadela, o que sublinha a sua função como complexo fortificado. O complexo foi construído no final do século XIX sob o emir Abdur Rahman Khan e tem servido como sede dos chefes de estado desde então. O complexo inclui não apenas os gabinetes oficiais do presidente, mas também áreas residenciais e edifícios administrativos, rodeados por muros altos. O Arg foi palco de inúmeros eventos históricos, desde golpes de estado a cerimónias solenes. As suas muralhas testemunharam a entrada e saída de reis, presidentes e governos. Como símbolo da autoridade estatal, o Arg é um local central e fortemente vigiado que encarna a história política complexa e muitas vezes turbulenta do Afeganistão.",
      fr: "L'Arg est le palais présidentiel de l'Afghanistan et le cœur battant du pouvoir à Kaboul. Le nom « Arg » signifie citadelle, ce qui souligne sa fonction de complexe fortifié. L'ensemble a été construit à la fin du XIXe siècle sous l'émir Abdur Rahman Khan et sert depuis de siège aux chefs d'État. Le complexe comprend non seulement les bureaux officiels du président, mais aussi des quartiers d'habitation et des bâtiments administratifs, entourés de hauts murs. L'Arg a été le théâtre d'innombrables événements historiques, des coups d'État aux cérémonies solennelles. Ses murs ont vu passer des rois, des présidents et des gouvernements. Symbole de l'autorité étatique, l'Arg est un lieu central et hautement sécurisé qui incarne l'histoire politique complexe et souvent turbulente de l'Afghanistan.",
    },
