      pt: ["Inaugurado no ano de 1967.", "Único jardim zoológico em todo o Afeganistão.", "O leão Marjan tornou-se um símbolo de sobrevivência.", "Gravemente danificado durante a guerra civil.", "Reconstruído com ajuda internacional.", "Local de lazer importante para as crianças em Cabul.", "Abriga principalmente espécies animais nativas.", "Localizado nas margens do rio Cabul."],
