      es: ["Monumento budista de la época Kushan.", "Sirvió como guía en la Ruta de la Seda.", "Ejemplo del arte de Gandhara.", "Originalmente una columna muy alta.", "Se encontraba en una cresta montañosa al sureste de Kabul.", "Testimonio del pasado budista de Afganistán.", "Dañado por guerras y terremotos.", "Completamente destruido en el año 1998."],
      pt: ["Monumento budista da era Kushan.", "Serviu como guia na Rota da Seda.", "Exemplo da arte de Gandhara.", "Originalmente uma coluna muito alta.", "Situado num cume de montanha a sudeste de Cabul.", "Testemunho do passado budista do Afeganistão.", "Danificado por guerras e sismos.", "Totalmente destruído no ano de 1998."],
      fr: ["Monument bouddhiste de l'époque kouchan.", "Servait de repère sur la Route de la Soie.", "Exemple de l'art du Gandhara.", "À l'origine, une colonne très haute.", "Situé sur une crête au sud-est de Kaboul.", "Témoignage du passé bouddhiste de l'Afghanistan.", "Endommagé par les guerres et les séismes.", "Entièrement détruit en 1998."],
